from pathlib import Path
import re
zones={}
for p in Path('.').glob('pc*/etc/bind/named.conf'):
 s=p.read_text(); m=re.search(r'zone \"(["'^"]+)" '"\\{ type master; file \"["'^"]*/(db.[''^"]+)";'"',s)
 if m: zones[m.group(1)]=(p.parent/m.group(2)).read_text()
assert len(zones)==16
for z,s in zones.items():
 assert ' IN SOA ' in s and '@ IN NS ' in s
 if z"'!='"'.':
  parent='.'.join(z.split('.')[1:]) or '.'
  assert f'{z}. IN NS ns.{z}.' in zones[parent]
  assert f'ns.{z}. IN A ' in zones[parent] and f'ns.{z}. IN A ' in s
for z in ('company.com','university.edu'): assert f'@ IN MX 10 mail.{z}.' in zones[z] and 'mail IN A ' in zones[z]
for n in range(1,41): assert 'nameserver 10.15.9.12' in Path(f'pc{n}.startup').read_text()
print('Static checks passed: 16 zones, delegations, glue, MX records and 40 client configurations.')
PY"

